# Final version of solution 3
n = 16
solution = []
for r in range(n):
    row = []
    for c in range(n):
        k = r - c
        if k < -14:
            val = 9
        elif -14 <= k <= -14:  # only k=-14
            val = 9
        elif 2 <= k <= 14:
            val = 1
        elif k == 15:
            val = 2
        else:  # k < 2 or k > 14 (but k>15 gets 0 or maybe different)
            if k > 14:
                val = 9
            else:
                val = 0
        row.append(val)
    solution.append(row)

output = solution
print(output)
